fn get_attached_file(var_attachment_id rt.PhpVal, unfiltered bool) rt.PhpVal {
	mut var_file := get_post_meta(var_attachment_id.dup(), '_wp_attached_file', true)
	if rt.is_true(rt.new_bool(rt.is_true(rt.new_bool(rt.is_true(var_file) && rt.is_true(rt.new_bool(!(rt.is_true(rt.call_function('str_starts_with', [var_file.dup(), rt.new_string('/')]))))))) && rt.is_true(rt.new_bool(!(rt.is_true(rt.call_function('preg_match', [rt.new_string('|^.:\\\\|'), var_file.dup()]))))))) {
		mut var_uploads := rt.call_function('wp_get_upload_dir', []rt.PhpVal{})
		if rt.is_true(rt.identical(rt.new_bool(false), var_uploads.array_get('error'))) {
			var_file = rt.new_string((var_uploads.array_get('basedir')).str() + "/${var_file.to_string()}")
		}
	}
	if var_unfiltered {
		return var_file.dup()
	}
	return rt.call_function('apply_filters', [rt.new_string('get_attached_file'), var_file.dup(), var_attachment_id.dup()])
}

fn update_attached_file(var_attachment_id rt.PhpVal, var_file rt.PhpVal) bool {
	if rt.is_true(rt.new_bool(!(rt.is_true(get_post(var_attachment_id.dup(), rt.new_null(), ''))))) {
		return false
	}
	var_file = rt.call_function('apply_filters', [rt.new_string('update_attached_file'), var_file.dup(), var_attachment_id.dup()])
	var_file = _wp_relative_upload_path(var_file.dup())
	if rt.is_true(var_file) {
		return (update_post_meta(var_attachment_id.dup(), rt.new_string('_wp_attached_file'), var_file.dup(), '')).to_bool()
	} else {
		return (delete_post_meta(var_attachment_id.dup(), '_wp_attached_file', '')).to_bool()
	}
	return false
}

